import html

def apply(pages,hero,section,card):
    pages.pop('investors-move',None);pages.pop('media-data',None)
    pages['']=('Business acquisition, development and advisory','Ritch Ventures is a business acquisition, development and advisory platform led by Robert Ritch.',hero('Ritch Ventures · Led by Robert Ritch',"The scale changes.<br>The fundamentals don't.",'We acquire, develop and advise businesses. Robert Ritch brings experience and judgment to important business decisions; Ritch Ventures evaluates acquisition and investment opportunities for Lock Equity.')+section('One platform. Three paths.','<div class="triptych"><article><p class="number">01 / ACQUIRE</p><h3>Explore a flexible ownership transition.</h3><p>Ritch Ventures evaluates established businesses for full or partial acquisition through Lock Equity.</p><p>Owner burnout, retirement and succession, partner disagreements, personal circumstances, financial distress, underperformance and other special situations can call for a flexible transaction structure.</p><a class="button" href="/contact/?type=acquisition">Discuss an Acquisition</a></article><article><p class="number">02 / ADVISE</p><h3>Work directly with Robert.</h3><p>Robert Ritch works with selected business owners facing important decisions, challenges and opportunities.</p><p>Engagements include ongoing advisory relationships and defined, fixed-fee projects.</p><a class="button" href="/contact/">Apply to Work With Robert</a></article><article><p class="number">03 / BUILD &amp; CONNECT</p><h3>Develop the business and the relationships.</h3><p>Ritch Ventures develops businesses, establishes distribution relationships and connects business owners with specialized service providers.</p><p>Independent specialists handle their respective services. Project-management responsibilities are agreed for each engagement.</p><a class="button" href="/our-businesses/">Explore Our Businesses</a></article></div>')+section('Start with the situation.','<p class="lead">You don’t need to know what you need before we talk. That’s part of the conversation.</p><ol class="steps"><li><strong>Tell us about the business.</strong> Share the decision, challenge or opportunity and what you want to accomplish.</li><li><strong>Review the fit.</strong> Applications are reviewed before a conversation is offered.</li><li><strong>Choose the next step.</strong> Advice, a defined project, a resource introduction or an acquisition discussion.</li></ol>')+section('Experience you can apply.','<div class="grid">'+card('Selective advisory','<p>Direct access to Robert’s experience and judgment through an ongoing relationship or a focused project.</p><p>Qualified applicants may be offered a complimentary initial conversation of approximately 30 minutes.</p>','Apply to Work With Robert','/contact/')+card('Flexible business transitions','<p>Complete or partial acquisitions, majority transactions, appropriate minority investments, seller financing and earnouts may be considered.</p><p>Every opportunity is evaluated individually. No transaction is promised.</p>','Discuss an Acquisition','/contact/?type=acquisition')+'</div>')+section('Businesses, distribution and specialist resources.','<div class="triptych"><article><h3>Our Businesses</h3><p>Business activities, brands and distribution relationships across media, technology, risk and other areas.</p><a href="/our-businesses/">Explore Our Businesses</a></article><article><h3>Specialist relationships</h3><p>Robert helps identify appropriate resources and may facilitate introductions.</p><a href="/resources/">Resources &amp; Referrals</a></article><article><h3>Robert’s perspective</h3><p>Articles, thought leadership and additional biography information.</p><a href="https://robertritch.com/">Visit RobertRitch.com</a></article></div>'))
    pages['robert-ritch']=('Robert Ritch','Robert Ritch brings business-building, acquisition, operating and investment experience to selective advisory engagements through Ritch Ventures.',hero('Robert Ritch','Experience and judgment for the decisions that matter.','Robert Ritch leads Ritch Ventures and provides personal advisory services through the platform. His work spans building, acquiring and operating businesses, investing and complex business situations.')+section('Business experience across different situations.','<p>Robert’s experience includes developing businesses, evaluating acquisitions, operating companies, investing, turnarounds and restructuring, capital strategy and business development.</p><p>He works with owners navigating growth, ownership transitions, difficult decisions and special situations. His role is to assess the situation, evaluate options, develop relationships and help determine a practical course of action.</p><p>When an engagement calls for project coordination, responsibilities are defined in the scope. Specialists fulfill their respective services; a referral does not automatically create a managed project.</p>')+section("The scale changes. The fundamentals don't.",'<p class="lead">Cash flow, profitability, sound capital decisions and a business that can operate effectively matter at every size.</p><p>Robert’s philosophy is to apply those business principles to the company in front of him—taking account of its resources, stage, constraints and owner’s objectives. The approach is practical: understand the issue before selecting a solution.</p>')+section('Articles, thought leadership and biography.','<p>RobertRitch.com remains Robert’s personal publishing and authority destination.</p><a class="button" href="https://robertritch.com/">Visit RobertRitch.com</a>'))
    pages['advisory']=('Work With Robert','Selective ongoing advisory relationships and defined fixed-fee projects with Robert Ritch through Ritch Ventures.',hero('Work With Robert','Direct access to experience and judgment.','Robert works with a limited number of business owners facing important decisions, challenges and opportunities. Personal advisory services are provided through Ritch Ventures.')+section('Two ways to work together.','<div class="grid">'+card('Ongoing advisory relationships','<p>A recurring relationship for owners who want an experienced perspective on decisions, priorities, growth, profitability and business challenges.</p><p>Access, availability, scope and fees are agreed before the engagement begins.</p>','Apply to Work With Robert','/contact/?interest=ongoing')+card('Defined, fixed-fee projects','<p>A focused engagement for a specific assessment, business decision, opportunity or special situation.</p><p>Deliverables, timing, responsibilities and fees are agreed in advance. Specialist work and any project-management role are defined in the engagement.</p>','Apply to Work With Robert','/contact/?interest=project')+'</div>')+section('A qualified first conversation.','<p class="lead">Qualified applicants may be offered a complimentary initial conversation of approximately 30 minutes.</p><p>The purpose is to understand the situation, assess fit and discuss an appropriate next step. It is not an ongoing free-consulting arrangement.</p><p>Applications are reviewed before calendar access is offered. Submitting an application does not automatically schedule a meeting or create an engagement.</p><a class="button" href="/contact/">Apply to Work With Robert</a>'))
    pages['acquisitions']=('Acquisitions and ownership transitions','Explore complete and partial acquisitions, investments and flexible business transition structures with Ritch Ventures and Lock Equity.',hero('Acquisitions & Lock Equity','A flexible approach to your next chapter.','Ritch Ventures evaluates established businesses and ownership transitions. Lock Equity may serve as the acquisition or investment vehicle.','Discuss an Acquisition','/contact/?type=acquisition')+section('Structure the conversation around the situation.','<div class="grid"><div><h3>Ownership and transaction structures</h3><ul><li>Complete business acquisitions.</li><li>Partial acquisitions.</li><li>Majority ownership transactions.</li><li>Minority investments where appropriate.</li><li>Seller-financed transactions.</li><li>Earnouts.</li></ul></div><div><h3>Situations we consider</h3><ul><li>Retirement and succession.</li><li>Owner burnout and personal circumstances.</li><li>Partner disputes.</li><li>Financial distress.</li><li>Underperforming businesses and turnaround opportunities.</li><li>Other special situations.</li></ul></div></div><p>The structure depends on the business, the owner’s objectives and the economics of the opportunity. Flexibility does not mean every business or proposed structure will be a fit.</p>')+section('Start with an initial summary.','<ol class="steps"><li>Tell us about the business, reason for a transaction, preferred exit and timing.</li><li>Robert reviews the opportunity and determines whether an initial conversation is appropriate.</li><li>Discuss confidentiality arrangements before sharing detailed financial documents.</li><li>If there is a fit, explore evaluation, structure and next steps.</li></ol><p>An inquiry is not an offer or a commitment. No acquisition, investment, financing or closing is promised.</p><div class="actions"><a class="button" href="/contact/?type=acquisition">Discuss an Acquisition</a><a href="/lock-equity/">About Lock Equity</a></div>'))
    pages['lock-equity']=('Lock Equity','Ritch Ventures identifies and evaluates business acquisition and investment opportunities for Lock Equity.',hero('Lock Equity','Acquisitions and investments, evaluated individually.','Ritch Ventures identifies and evaluates acquisition and investment opportunities for Lock Equity, which may serve as the acquisition or investment vehicle.','Discuss an Acquisition','/contact/?type=acquisition')+section('The right structure depends on the business.','<p>Complete or partial acquisitions, majority ownership, appropriate minority investments, seller financing and earnouts may be considered according to the situation.</p><p>Participating entities, terms and responsibilities are determined for each opportunity. No transaction is promised. This website is not an offer to buy or sell securities.</p><a href="/acquisitions/">Explore Acquisitions</a>'))
    businesses=[('Media Consolidation Group','Audience data, advertising and media placement.','https://mediaconsolidationgroup.com/'),('Paladin Risk Control','Risk management and intelligence services.','https://paladinriskcontrol.com/'),('Secured Equity Group','Portfolios of notes and institutional transactions.','https://securredequitygroup.com/'),('Simple Marketing Platform','CRM, automation and related business technology.','https://simplemarketingplatform.com/'),('Tech Services Done Right','Call center, customer support and technology services.','https://techservicesdoneright.com/'),('Omni Benefits','Employee benefits and related business services.',None),('Arrowheart','Publishing, content and marketing services.',None),('Adventure Protection Group','RV and marine warranty distribution.',None),('Renova Distribution','Product distribution activities, subject to final commercial agreements.',None),('Investors Move','Company interviews and investor-focused media.','https://investorsmove.com/')]
    directory=''.join('<article><h3>'+name+'</h3><p>'+desc+'</p>'+('<a href="'+url+'">Visit '+name+'</a>' if url else '')+'</article>' for name,desc,url in businesses)
    pages['our-businesses']=('Our Businesses','Explore Ritch Ventures business activities, brands and distribution relationships.',hero('Our Businesses','Businesses and relationships that move opportunities forward.','Ritch Ventures develops businesses, establishes distribution relationships and connects opportunities with specialized capabilities.','Apply to Work With Robert','/contact/')+section('Business activities and brands.','<p>These activities include operating brands and distribution relationships. Listing a business does not imply ownership of an independent supplier or manufacturer. Each engagement identifies the responsible entity, scope and relevant relationship.</p><div class="directory">'+directory+'</div>')+section('Clear roles and commercial relationships.','<p>Independent providers, manufacturers and administrators are responsible for their respective products and services unless otherwise agreed. Ritch Ventures does not manage every referred engagement.</p><p>Relevant ownership, affiliate and referral-compensation relationships are disclosed when a recommendation or engagement is discussed.</p>'))
    pages['resources']=('Resources and Referrals','Robert Ritch helps identify specialist resources and may facilitate business introductions.',hero('Resources & Referrals','Find the expertise the situation calls for.','Robert maintains relationships with specialists and helps business owners identify appropriate resources. He may facilitate introductions when there is a fit.')+section('Specialist relationships across the business.','<div class="triptych"><article><h3>Finance and transactions</h3><p>Financing, accounting and CFO services, legal services and banking.</p></article><article><h3>Systems and growth</h3><p>Technology, marketing and payments.</p></article><article><h3>People and operations</h3><p>HR and benefits, risk management and business operations.</p></article></div>')+section('An introduction with clear responsibilities.','<p>Independent providers are responsible for their own services unless otherwise agreed. An introduction does not automatically mean that Ritch Ventures manages the project.</p><p>Any project-management responsibilities are defined in an engagement. Relevant ownership, affiliate and referral-compensation relationships are disclosed with the recommendation.</p><a class="button" href="/contact/">Apply to Work With Robert</a>'))
    pages['contact']=('Apply or discuss an acquisition','Apply to work with Robert Ritch or share an initial business acquisition inquiry.',hero('Start a conversation','Tell us about the business and the decision.','Choose an advisory application or acquisition inquiry. Applications are reviewed before an initial conversation or calendar access is offered.','Explore Advisory','/advisory/')+'<section class="wrap section formwrap"><div class="actions form-switch"><button class="button" type="button" data-form="application" aria-pressed="true">Apply to Work With Robert</button><button class="button" type="button" data-form="acquisition" aria-pressed="false">Acquisition Inquiry</button></div><hr>'+form(False)+form(True)+'</section>')
    pages['privacy']=('Privacy Policy','How Ritch Ventures uses initial business inquiry information.', '<section class="wrap section"><h1 style="font-size:42px">Privacy Policy</h1><p class="small">Effective date: October 8, 2026</p><h2>Information you provide</h2><p>Ritch Ventures collects the information you choose to submit through an advisory application or acquisition inquiry. This includes your name, email, company, website, business stage or industry, approximate revenue and your description of the situation, objectives, exit preference and timing.</p><h2>How information is used</h2><p>Information is used to review fit, respond to the inquiry and discuss requested next steps. Submitting a form does not enroll you in an engagement, subscribe you to marketing or automatically schedule a meeting.</p><h2>Processing and sharing</h2><p>For the intended Netlify production website, Netlify processes and stores submissions and sends configured notifications. Robert Ritch and authorized people assisting with inquiry review may access the information. If an introduction or specialist engagement is appropriate, discuss what information should be shared and with whom before proceeding.</p><p>Independent providers have their own service terms and privacy practices. Hosting providers may process technical request information necessary to deliver and protect the website.</p><h2>Storage and your requests</h2><p>Inquiry information is kept for the inquiry and related business discussions. Contact us to request access, correction or deletion, or to ask about retention. Any applicable recordkeeping requirements will be considered when responding.</p><h2>Sensitive information</h2><p>Do not send confidential financial documents, account details, government identification or sensitive personal information through these initial forms. Discuss confidentiality and an appropriate exchange process first.</p><h2>Cookies and marketing</h2><p>This website does not add marketing trackers or analytics cookies. Hosting and security services may use technical information to operate the website.</p><h2>Contact</h2><p>For privacy questions, contact <a href="mailto:robertritch@ritchventures.com">robertritch@ritchventures.com</a>.</p><div class="privacy-review notice"><strong>Temporary preview:</strong> these forms do not send or store inquiries. Production processing and the responsible legal entity must be confirmed before launch.</div></section>')
    pages['thank-you']=('Application submitted','Next steps after a Ritch Ventures inquiry.','<section class="wrap section"><h1 style="font-size:42px">Thank you for your inquiry.</h1><p class="lead">If you arrived here after a successful form submission, your inquiry has been submitted for review.</p><p>Applications are reviewed before a conversation or calendar access is offered. There is no automatic appointment.</p><p>An inquiry does not create an engagement or commit either party to a transaction.</p><a class="button" href="/">Return to Ritch Ventures</a></section>')
    pages['404']=('Page Not Found','Find the right page at Ritch Ventures.','<section class="wrap section"><h1 style="font-size:42px">That page could not be found.</h1><p>Explore advisory, acquisitions, businesses and resources from the main website.</p><a class="button" href="/">Return Home</a></section>')

def field(prefix,name,label,kind='text',required=True,options=None,limit=None,autocomplete=None):
    eid=prefix+'-'+name;attrs=' id="'+eid+'" name="'+name+'"'+(' required' if required else '')+(' maxlength="'+str(limit)+'"' if limit else '')+(' autocomplete="'+autocomplete+'"' if autocomplete else '')
    if options:
        control='<select'+attrs+'><option value="">Select an option</option>'+''.join('<option>'+html.escape(o)+'</option>' for o in options)+'</select>'
    elif kind=='textarea':control='<textarea'+attrs+'></textarea>'
    else:control='<input type="'+kind+'"'+attrs+'>'
    return '<label for="'+eid+'">'+label+(' (optional)' if not required else '')+'</label>'+control

def form(acq):
    prefix='acq' if acq else 'app';name='acquisition-inquiry' if acq else 'advisory-application';kind='acquisition' if acq else 'application'
    common=field(prefix,'name','Name',limit=150,autocomplete='name')+field(prefix,'email','Email','email',limit=254,autocomplete='email')+field(prefix,'company','Company',limit=200,autocomplete='organization')+field(prefix,'website','Website','url',required=False,limit=500)
    revenue=field(prefix,'annual-revenue','Approximate annual revenue',options=['Pre-revenue','Under $250,000','$250,000–$999,999','$1 million–$4.99 million','$5 million–$9.99 million','$10 million or more','Prefer to discuss'])
    if acq:
        body=common+field(prefix,'industry','Industry',limit=200)+revenue+field(prefix,'transaction-reason','Reason for considering a transaction','textarea',limit=2000)+field(prefix,'exit-preference','Full or partial exit preference',options=['Full exit','Partial exit','Open to discussing either'])+field(prefix,'desired-timing','Desired timing',limit=200)+field(prefix,'situation','Brief description of the situation','textarea',limit=5000)
        title='Acquisition Inquiry';intro='Share an initial summary. Do not submit confidential financial documents through this form. Confidentiality arrangements and detailed materials can be discussed later.';button='Send Acquisition Inquiry'
    else:
        body=common+field(prefix,'business-stage','Business stage',options=['Idea stage','Pre-revenue','Early revenue','Established business','Growth/expansion','Distressed/turnaround'])+revenue+field(prefix,'situation','Brief description of the business situation','textarea',limit=5000)+field(prefix,'objective','What are you trying to accomplish?','textarea',limit=5000)
        title='Apply to Work With Robert';intro='Applications are reviewed before offering calendar access. Qualified applicants may be offered a complimentary initial conversation of approximately 30 minutes. No appointment is automatically scheduled.';button='Send Application'
    return '<div class="form-panel" id="'+kind+'"><h2>'+title+'</h2><p>'+intro+'</p><form name="'+name+'" method="POST" action="/thank-you/" data-netlify="true" netlify-honeypot="bot-field"><input type="hidden" name="form-name" value="'+name+'"><p hidden><label>Leave this empty<input name="bot-field" tabindex="-1" autocomplete="off"></label></p>'+body+'<p class="small">Your information is used to review and respond to this inquiry. See the <a href="/privacy/">Privacy Policy</a>. Please omit sensitive personal information.</p><button class="button" type="submit">'+button+'</button><p role="status" aria-live="polite" class="notice hidden"></p></form></div>'
